test('inbound busy after retained evidence retries the queue without acknowledgement',async()=>{const h=expenseSqlite(),router=require('../dist/router/process-event.js'),worker=require('../dist/index.js').default,{InboundBusyError}=require('../dist/db/repositories.js'),old=router.processInbound;let ack=0,retries=0,delay=0;try{router.processInbound=async()=>{throw new InboundBusyError();};await worker.queue({queue:'malipang-jobs',messages:[{body:{kind:'LINE_EVENT',event:{},traceId:'image-retry',receivedAtIso:'2026-11-15T00:00:00Z'},attempts:1,ack(){ack++;},retry(x){retries++;delay=x?.delaySeconds;}}]},h.env,{});assert.equal(ack,0);assert.equal(retries,1);assert.equal(delay,300);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM failed_jobs').get().n,0);}finally{router.processInbound=old;h.close();}});
